INSERT INTO weather_alert (alert_type, alert_level, message, triggered_at)
SELECT #{alertType}, #{alertLevel}, #{message}, NOW()
WHERE NOT EXISTS (
    SELECT 1 FROM weather_alert
    WHERE alert_type = #{alertType}
      AND alert_level = #{alertLevel}
      AND resolved_at IS NULL
      AND DATE(triggered_at) = CURDATE()
)
